// 11. End card: the mark and wordmark build as in the title, the box line tracks in beneath, the
// last hit of the music glints off the mark, then the credits: the music is machine-generated by
// MiniMax-Music3 on this box (its licence asks for the credit), footage from Pexels and Pixabay.
// Technique: lockup with tracking-in type; fine print fades in; fade to black.
import { R } from '../main.js'
import { chainAt, drawMark } from '../lib/logo.js'
import { inOutCubic, mix, outExpo, prog, spring } from '../lib/ease.js'

const K = 11 // px per logo unit: a 264 px mark
const MARK = 24 * K
const TEXT_PX = (15 / 22) * MARK

export default function endcard(T) {
  const s = { id: 'endcard', z: 11 }
  let fx, word, tag, fine, markCx, cy = 470
  const b28 = T.bar(28), b29 = T.bar(29)
  s.build = (root) => {
    root.style.background = '#040506'
    fx = R.canvas(root)
    word = R.el('div', '', root, 'tacit')
    word.style.cssText = `position:absolute;font-size:${TEXT_PX}px;font-weight:600;letter-spacing:-0.03em;line-height:1;color:#eceef1;white-space:nowrap`
    tag = R.el('div', 'mono abs', root, 'Nine models · four Tenstorrent chips · one box')
    tag.style.cssText += ';left:0;right:0;text-align:center;top:640px;font-size:30px;color:#a3a9b2;white-space:nowrap'
    fine = R.el('div', 'abs', root,
      'Music: MiniMax-Music3, machine-generated on chip 1 of this box &nbsp;·&nbsp; Footage: Anastasia Shuraeva, Pexels; ' +
      'AI-made comparison clip: flutie8211, Pixabay')
    fine.style.cssText = 'left:0;right:0;bottom:64px;text-align:center;font-family:"Geist Mono",monospace;font-size:17px;letter-spacing:0.02em;color:#6e7580'
    root.style.display = 'block'
    const r = word.getBoundingClientRect()
    root.style.display = ''
    const gap = MARK * (8 / 22)
    const total = MARK + gap + r.width
    markCx = 960 - total / 2 + MARK / 2
    word.style.left = `${markCx + MARK / 2 + gap}px`
    word.style.top = `${cy - r.height / 2 - TEXT_PX * 0.04}px`
  }
  s.render = (t) => {
    const t0 = b28 + 0.35
    fx.clear()
    const box = spring(t, t0, { zeta: 0.6, omega: 13 })
    const ring = spring(t, t0 + 0.15, { zeta: 0.55, omega: 12 })
    const glint = t >= b29 ? Math.exp(-(t - b29) * 2.2) : 0
    if (t >= t0) drawMark(fx.g, markCx, cy, K, { pts: chainAt(markCx, cy, K), box: Math.max(0, box), ring: Math.max(0, ring) + glint * 0.6, glow: 1.1 + glint * 2.5 })
    const wipe = prog(t, t0 + 0.08, 0.7, outExpo)
    word.style.clipPath = `inset(-20% ${(1 - wipe) * 100}% -20% 0)`
    word.style.transform = `translateX(${(1 - wipe) * -50}px)`
    const kt = prog(t, b28 + 1.0, 1.1, outExpo)
    tag.style.opacity = String(kt)
    tag.style.letterSpacing = `${mix(0.5, 0.22, kt)}em`
    fine.style.opacity = String(prog(t, b29 + 0.6, 0.9, inOutCubic))
    // Fade to black at the very end.
    const end = prog(t, s.end - 0.7, 0.7, inOutCubic)
    s.layer.style.opacity = String(1 - end)
  }
  return s
}
